### 1. Add a small cache module

```javascript
// weatherCache.js
const STORAGE_KEY = 'weather_responses_v1';
const TTL = 60 * 60 * 1000; // 1 hour
const MAX_ENTRIES = 3;

function loadEntries() {
  try {
    const entries = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
    return Array.isArray(entries) ? entries : [];
  } catch {
    return []; // Unavailable storage or invalid JSON
  }
}

let entries = loadEntries();

function persist() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(entries));
  } catch {
    // Keep using the in-memory cache if storage is full or blocked.
  }
}

export function getCachedWeather(key) {
  const now = Date.now();
  entries = entries.filter(entry => entry && entry.expires > now);

  const index = entries.findIndex(entry => entry.key === key);
  if (index === -1) return null;

  // Move the accessed city to the front without extending its expiry.
  const [entry] = entries.splice(index, 1);
  entries.unshift(entry);
  persist();

  return entry.data;
}

export function cacheWeather(key, data) {
  entries = entries.filter(
    entry => entry && entry.key !== key && entry.expires > Date.now()
  );

  entries.unshift({
    key,
    data,
    expires: Date.now() + TTL,
  });

  entries = entries.slice(0, MAX_ENTRIES);
  persist();
}

export function clearWeatherCache() {
  entries = [];
  persist();
}
```

### 2. Check the cache before fetching

```javascript
// apiClient.js
import { getCachedWeather, cacheWeather } from './weatherCache.js';

const API_KEY = 'YOUR_API_KEY';

export async function fetchWeatherData(city) {
  if (typeof city !== 'string' || !city.trim()) {
    throw new Error('Please enter a city name.');
  }

  const name = city.trim();
  const key = `metric:${name.toLowerCase()}`;
  const cached = getCachedWeather(key);

  if (cached !== null) return cached;

  const url = new URL('https://api.openweathermap.org/data/2.5/weather');
  url.search = new URLSearchParams({
    q: name,
    units: 'metric',
    appid: API_KEY,
  });

  let response;
  try {
    response = await fetch(url);
  } catch {
    throw new Error('Network error: Failed to retrieve weather data.');
  }

  if (!response.ok) {
    const messages = {
      400: 'Invalid request',
      401: 'Invalid API key',
      404: 'City not found',
      429: 'Too many requests. Please try again later.',
    };

    throw new Error(
      `HTTP ${response.status}: ${messages[response.status] || 'Weather request failed'}`
    );
  }

  const data = await response.json();

  if (!Number.isFinite(data?.main?.temp) || !data?.weather?.length) {
    throw new Error('Invalid weather response.');
  }

  cacheWeather(key, data);
  return data;
}
```

### How it behaves

- A repeated city search uses cached data without an API call.
- Responses expire **one hour after fetching**.
- Only the **three most recently used cities** are retained.
- Cached responses survive page reloads when localStorage is available.
- Failed requests are **not cached**.

Your UI should catch errors from `fetchWeatherData()` and display them. Also, browser caching reduces calls but **does not enforce your account-wide API quota**.

**API-key note:** The placeholder above follows your direct-browser request approach, but browser code cannot keep an API key secret—even with a `.env` file. If key secrecy is required, make the request through a server-side proxy.

