// apiCache.js
const cache = new Map();
const TTL = 5 * 60 * 1000;
const MAX_ENTRIES = 100; // Suggested cap to keep memory usage bounded

export async function getCachedData(key, fetchData) {
  const entry = cache.get(key);

  if (entry && Date.now() < entry.expiresAt) {
    return entry.data;
  }

  cache.delete(key);

  // If fetching throws, nothing is cached.
  const data = await fetchData();

  // Your existing error handling may return null on failure.
  if (data == null) return data;

  if (cache.size >= MAX_ENTRIES) {
    cache.delete(cache.keys().next().value);
  }

  cache.set(key, {
    data,
    expiresAt: Date.now() + TTL
  });

  return data;
}

export function clearApiCache() {
  cache.clear();
}
```

