You previously wanted to keep the **three most recently searched cities** with timestamps. Here’s a simple implementation using **one-hour expiration** that preserves cached responses across page reloads.

```javascript
// apiClient.js
const STORAGE_KEY = "weatherApp:responses:v1";
const TTL = 60 * 60 * 1000; // 1 hour
const MAX_CITIES = 3;

function loadCache() {
  try {
    const entries = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!Array.isArray(entries)) return [];

    return entries.filter(entry =>
      entry &&
      typeof entry.key === "string" &&
      Number.isFinite(entry.timestamp) &&
      entry.data &&
      Date.now() - entry.timestamp < TTL
    ).slice(0, MAX_CITIES);
  } catch {
    return [];
  }
}

let cache = loadCache();

function saveCache() {
  try {
    // Only update our own key; leave other stored data untouched.
    localStorage.setItem(STORAGE_KEY, JSON.stringify(cache));
  } catch {
    // If storage is full or unavailable, the in-memory cache still works.
  }
}

export async function getWeather(city, apiKey) {
  if (typeof city !== "string" || !city.trim()) {
    throw new Error("Please enter a city.");
  }

  const query = city.trim();
  const key = `${query.toLowerCase()}|metric`;
  const now = Date.now();

  cache = cache.filter(entry => now - entry.timestamp < TTL);

  const index = cache.findIndex(entry => entry.key === key);

  if (index !== -1) {
    // Move this city to the front without extending its expiration.
    const [entry] = cache.splice(index, 1);
    cache.unshift(entry);
    saveCache();
    return entry.data;
  }

  const params = new URLSearchParams({
    q: query,
    appid: apiKey,
    units: "metric"
  });

  const response = await fetch(
    `https://api.openweathermap.org/data/2.5/weather?${params}`
  );

  if (!response.ok) {
    throw new Error(`Weather request failed (${response.status}).`);
  }

  const data = await response.json();

  if (!data.main || !Array.isArray(data.weather)) {
    throw new Error("The weather API returned an unexpected response.");
  }

  cache.unshift({ key, timestamp: Date.now(), data });
  cache = cache.slice(0, MAX_CITIES);
  saveCache();

  return data;
}
```

Usage:

```javascript
try {
  const weather = await getWeather("London", "YOUR_API_KEY");
  console.log(weather.main.temp);
} catch (error) {
  console.error(error.message);
}
```

**How it works:**
- A repeat search within one hour returns cached data without an API call.
- Expired or missing data is fetched only when requested—no background refresh timer.
- Only the three most recently searched cities are retained.
- Failed requests are not cached, and unrelated `localStorage` data is not overwritten.

**Two important limits:** This reduces requests but does **not guarantee staying below your 1,000-call daily quota**—each browser has a separate cache. Also, API keys included in browser code are visible to users; use a backend proxy if your key must remain private.

